package com.automusicshorts.acquisitionsmoke

import androidx.test.ext.junit.runners.AndroidJUnit4
import org.junit.Assert.assertEquals
import org.junit.Assert.assertThrows
import org.junit.Test
import org.junit.runner.RunWith

@RunWith(AndroidJUnit4::class)
class BootstrapEnvelopeTest {
    // Generated by the Python V2 publisher with a fixed nonce and synthetic pairing token.
    private val value = "v1.AAECAwQFBgcICQoLLKGAAZjHIsaaMKzQDL5mkKJ-aVxiyOZ3sef1r79Jwqtb8X6srVo4slvYKlzPUVkOv0RfGvHmQQSnRHrAen6xlkRgzmXAZu0Cs9orwSpsZqx0OdPZM6JyIvivl1ZCdtKxdh2sM7Wv3yapTycpOehOPQDMUexD6PwUtrgD3WbvRDDMUktbm33cA6iW9qr0ZyRpyA"
    private val generation = 1720000000000000042L

    private fun open(
        envelope: String = value,
        token: String = "A".repeat(43),
        repo: Long = 1357480822L,
        space: Long = 53142444L,
        now: Long = 1720000001L,
        previous: Long = 0L,
    ) = BootstrapEnvelope.open(envelope, token, repo, space, now, previous)

    @Test fun opensPythonEnvelopeWithoutLosingNanosecondGeneration() {
        val result = open(previous = generation - 1)
        assertEquals("https://music-qa-demo.trycloudflare.com", result.url)
        assertEquals(generation, result.generation)
        assertEquals(1720000000L, result.issuedAt)
        assertEquals(1720000600L, result.expiresAt)
    }

    @Test fun rejectsWrongPairingAndTargetOrModifiedCiphertext() {
        val outcomes = listOf(
            { open(token = "B".repeat(43)) },
            { open(repo = 1357480823L) },
            { open(space = 53142445L) },
            { open(envelope = value.replaceRange(30, 31, "B")) },
        )
        for (attempt in outcomes) {
            assertEquals("CONNECTION_AUTHENTICATION_FAILED",
                assertThrows(BootstrapEnvelopeException::class.java) { attempt() }.message)
        }
    }

    @Test fun rejectsExpiredFutureAndReplayedDescriptor() {
        assertEquals("CONNECTION_NOT_CURRENT",
            assertThrows(BootstrapEnvelopeException::class.java) { open(now = 1720000600L) }.message)
        assertEquals("CONNECTION_NOT_CURRENT",
            assertThrows(BootstrapEnvelopeException::class.java) { open(now = 1719999969L) }.message)
        assertEquals("CONNECTION_REPLAY",
            assertThrows(BootstrapEnvelopeException::class.java) { open(previous = generation) }.message)
    }
}
